/* The guest SDK, compiled into the arcade1 CLI.
 *
 * tools/sdk_data.c is GENERATED by the Makefile from the real files in
 * programs/ (via tools/gen_sdk_data.awk), so `programs/` stays the single
 * source of truth and the CLI carries its own copy. That is what makes
 * `arcade1 build` self-contained: it works in any directory, with no
 * checkout, no build/ tree and no packarc1 helper beside it.
 *
 * Each array is NUL-terminated and holds the file verbatim, newline and
 * all. Regenerated whenever programs/ changes.
 */
#ifndef ARCADE1_SDK_DATA_H
#define ARCADE1_SDK_DATA_H

extern const char sdk_crt0_S[];       /* programs/crt0.S       */
extern const char sdk_link_ld[];      /* programs/link.ld      */
extern const char sdk_arcade1_h[];    /* programs/arcade1.h    */
extern const char sdk_gfx_h[];        /* programs/gfx.h        */
extern const char sdk_arcade1_map_h[];/* programs/arcade1_map.h */
extern const char sdk_asset_h[];      /* programs/asset.h      */
extern const char sdk_text_h[];       /* programs/text.h       */

/* The embedded set itself, in the order the Makefile embeds it. Generated
 * from the same list that produces the arrays above, so `arcade1 info` can
 * report the SDK headers the CLI really carries without hand-typing them
 * (ROADMAP_V4 card 4.1). */
typedef struct arcade1_sdk_file {
    const char *name;   /* e.g. "arcade1.h" — the file name inside the image */
    const char *text;   /* the file, verbatim */
} arcade1_sdk_file_t;

extern const arcade1_sdk_file_t sdk_files[];
extern const unsigned sdk_file_count;

#endif /* ARCADE1_SDK_DATA_H */
